import fs from 'fs';
import { uploadFileData } from './uploadFileData.js';
// Payload skips the original of a verified direct browser upload, so every file here
// must be written. `storageFilePath` already includes the prefixes and `_objectKey`.
export const getHandleUpload = ({ client, collection })=>{
    return async ({ data, file, storageFilePath })=>{
        const fileData = file.tempFilePath ? fs.readFileSync(file.tempFilePath) : file.buffer;
        await uploadFileData({
            client,
            collectionId: collection.slug,
            fileData,
            fileKey: storageFilePath,
            fileSize: file.filesize || fileData.length,
            mimeType: file.mimeType
        });
        return data;
    };
};
